import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        retries_429 = 3
        backoff_times = [0.5, 1, 2]

        # Handle 429 with exponential backoff
        for attempt in range(retries_429):
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                # Check if it's a 429 (though urlopen raises HTTPError for non-2xx)
                if response.status == 429:
                    if attempt < retries_429 - 1:
                        time.sleep(backoff_times[attempt])
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {retries_429} retries")
                # If we get here, it's a successful response (2xx)
                return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt < retries_429 - 1:
                        time.sleep(backoff_times[attempt])
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {retries_429} retries")
                elif e.code >= 500:
                    # Server error: retry once after 1s
                    time.sleep(1)
                    # Retry once
                    try:
                        req = urllib.request.Request(url)
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as e2:
                        if e2.code >= 500:
                            raise ServerError(f"Server error: {e2.code}")
                        elif e2.code >= 400:
                            raise ClientError(f"Client error: {e2.code}")
                        else:
                            raise
                    except urllib.error.URLError as e2:
                        raise ConnectionError(f"Connection error: {e2}")
                elif e.code >= 400:
                    # Client error (except 429, which is handled above)
                    raise ClientError(f"Client error: {e.code}")
                else:
                    raise
            except urllib.error.URLError as e:
                # Network error: retry once after 1s
                time.sleep(1)
                try:
                    req = urllib.request.Request(url)
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.HTTPError as e2:
                    if e2.code == 429:
                        raise RateLimitError(f"Rate limited: {e2.code}")
                    elif e2.code >= 500:
                        raise ServerError(f"Server error: {e2.code}")
                    elif e2.code >= 400:
                        raise ClientError(f"Client error: {e2.code}")
                    else:
                        raise
                except urllib.error.URLError as e2:
                    raise ConnectionError(f"Connection error: {e2}")
